from math import gcd
for p in range(1,45):
    for q in range(1,45):
        if gcd(p,q)==1:
            assert 2*sum(k*p//q for k in range(1,q))==(p-1)*(q-1)
assert [k*5//8 for k in range(1,8)]==[0,1,1,2,3,3,4] and sum(k*5//8 for k in range(1,8))==14==4*7//2
for p in range(3,45,2):
    for q in range(3,45,2):
        if gcd(p,q)==1:
            assert 4*(sum(k*p//q for k in range(1,(q-1)//2+1))+sum(j*q//p for j in range(1,(p-1)//2+1)))==(p-1)*(q-1)

def tau(k):
    return sum(1 for d in range(1,k+1) if k%d==0)
T=[0]
for k in range(1,201): T.append(T[-1]+tau(k))
for n in range(1,201):
    assert sum(n//d for d in range(1,n+1))==T[n]
assert sum(100//d for d in range(1,101))==482==T[100]

n=4
pc=lambda m: bin(m).count('1')
subs=list(range(1<<n))
def maxfam(ok):
    best=[0]
    def ext(fam,start):
        if len(fam)>best[0]: best[0]=len(fam)
        for c in range(start,len(subs)):
            if all(ok(pc(subs[c]&f)) for f in fam):
                ext(fam+[subs[c]],c+1)
    ext([],0)
    return best[0]
assert maxfam(lambda k: k in (0,1))==11==1+4+6
assert maxfam(lambda k: k==1)==4
assert maxfam(lambda k: k==2)==4
assert maxfam(lambda k: k==0)==5

import sympy as sp
for m in range(1,12):
    J=sp.ones(m,m); I=sp.eye(m)
    assert ((J-I)**2).applyfunc(lambda x: x%2)==(m*J+I).applyfunc(lambda x: x%2)
    assert ((J-I).det()%2==1)==(m%2==0)
pc=lambda x: bin(x).count('1')
for n in (4,5):
    cand=[x for x in range(1<<n) if pc(x)%2==0]
    best=[0]
    def ext(fam,start):
        best[0]=max(best[0],len(fam))
        for c in range(start,len(cand)):
            if all(pc(cand[c]&f)%2==1 for f in fam):
                ext(fam+[cand[c]],c+1)
    ext([],0)
    assert best[0]<=n+1

n=5
pc=lambda m: bin(m).count('1')
def mx(lam):
    best=[0]
    def ext(fam,start):
        best[0]=max(best[0],len(fam))
        for c in range(start,1<<n):
            if all(pc(c&f)==lam for f in fam): ext(fam+[c],c+1)
    ext([],0); return best[0]
assert mx(1)==5 and mx(2)<=5 and mx(3)==5 and mx(0)==6

